	private enum ResultMode {
		BLOCK,
		CANCELLATION,
		ERROR
	}

	private static final class ResultControl {

		private final ResultMode mode;
		private final CountDownLatch started = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);
		private final CountDownLatch closed = new CountDownLatch(1);
		private final AtomicInteger hasNextCalls = new AtomicInteger();
		private final AssertionError error = new AssertionError("remote result error");

		private ResultControl(ResultMode mode) {
			this.mode = mode;
		}

		private void release() {
			release.countDown();
		}
	}

	private static final class ControlledTupleQueryResult implements TupleQueryResult {

		private final TupleQueryResult delegate;
		private final ResultControl control;
		private final AtomicBoolean closed = new AtomicBoolean();

		private ControlledTupleQueryResult(TupleQueryResult delegate, ResultControl control) {
			this.delegate = delegate;
			this.control = control;
		}

		@Override
		public List<String> getBindingNames() throws QueryEvaluationException {
			return delegate.getBindingNames();
		}

		@Override
		public boolean hasNext() throws QueryEvaluationException {
			int call = control.hasNextCalls.incrementAndGet();
			if (control.mode == ResultMode.ERROR) {
				control.started.countDown();
				throw control.error;
			}
			if (control.mode == ResultMode.CANCELLATION) {
				control.started.countDown();
				throw new QueryInterruptedException("remote result cancelled");
			}
			if (call == 1) {
				control.started.countDown();
				try {
					control.release.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new QueryInterruptedException("remote result interrupted", e);
				}
				if (closed.get()) {
					return false;
				}
			}
			return delegate.hasNext();
		}

		@Override
		public BindingSet next() throws QueryEvaluationException {
			return delegate.next();
		}

		@Override
		public void remove() throws QueryEvaluationException {
			delegate.remove();
		}

		@Override
		public void close() throws QueryEvaluationException {
			if (closed.compareAndSet(false, true)) {
				try {
					delegate.close();
				} finally {
					control.release();
					control.closed.countDown();
				}
			}
		}
	}

	private static void await(CountDownLatch latch, String description) {
		try {
			assertTrue(latch.await(5, TimeUnit.SECONDS), "timed out waiting for " + description);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while waiting for " + description, e);
		}
	}

	private static void shutdownExecutor(ExecutorService executor) {
		executor.shutdownNow();
		try {
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "executor did not terminate");
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while stopping executor", e);
		}
	}
